// Concatenates every migration + the seed into supabase/setup.sql — one file to paste into
// the Supabase SQL editor for a brand-new project.   npm run db:bundle
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'

const dir = new URL('../supabase/', import.meta.url)
const migrations = readdirSync(new URL('migrations/', dir)).filter((f) => f.endsWith('.sql')).sort()
const parts = [
  '-- CampusFix — complete database setup for a NEW Supabase project.',
  '-- GENERATED by scripts/bundle-setup-sql.mjs from supabase/migrations/* and supabase/seed.sql. Do not edit by hand.',
  '-- Paste into Supabase → SQL Editor → New query → Run. Run it once.',
  '',
]
for (const f of migrations) parts.push(`-- ===== migrations/${f} =====`, readFileSync(new URL(`migrations/${f}`, dir), 'utf8'), '')
parts.push('-- ===== seed.sql (fictional sample data) =====', readFileSync(new URL('seed.sql', dir), 'utf8'))
writeFileSync(new URL('setup.sql', dir), parts.join('\n'))
console.log(`supabase/setup.sql written (${migrations.length} migrations + seed)`)
